import{_ as i,C as e,o as s,c,E as a,a7 as d}from"./chunks/framework.FWlv_suP.js";const b=JSON.parse('{"title":"MetroPocket Privacy Policy","description":"MetroPocket privacy policy, presented within Policy Hub.","frontmatter":{"title":"MetroPocket Privacy Policy","description":"MetroPocket privacy policy, presented within Policy Hub."},"headers":[],"relativePath":"apps/metro-pocket/privacy.md","filePath":"apps/metro-pocket/privacy.md"}'),l={name:"apps/metro-pocket/privacy.md"};function p(h,o,u,m,f,v){const t=e("AppBreadcrumbs"),r=e("AppSubnav"),n=e("CopyStandaloneUrl");return s(),c("div",null,[a(t,{"app-id":"metro-pocket",current:"Privacy Policy"}),a(r,{"app-id":"metro-pocket"}),a(n,{path:"/privacy/metro-pocket",label:"Copy standalone privacy policy URL","copied-label":"Privacy Policy URL copied","document-name":"MetroPocket privacy policy"}),o[0]||(o[0]=d('<h1 id="privacy-policy-for-metropocket" tabindex="-1">Privacy Policy for MetroPocket <a class="header-anchor" href="#privacy-policy-for-metropocket" aria-label="Permalink to &quot;Privacy Policy for MetroPocket&quot;">​</a></h1><p><strong>Effective Date:</strong> October 13, 2026<br><strong>Last Updated:</strong> October 14, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>MetroPocket is an offline-first metro route, TV channel, and personal train-schedule reference app developed by <strong>Anand Raja</strong>. It is available for Android and the web. It has no account, advertising, developer-operated analytics, tracking SDK, or developer-operated cloud database.</p><h2 id="information-kept-on-your-device" tabindex="-1">Information kept on your device <a class="header-anchor" href="#information-kept-on-your-device" aria-label="Permalink to &quot;Information kept on your device&quot;">​</a></h2><p>MetroPocket stores downloaded data packs and their metadata in app-private browser/WebView storage. These packs supply metro network and TV channel information for offline use. A theme preference may be stored locally. Route choices, searches, and saved train schedules are processed locally; they are not sent to the developer.</p><p>On Web/PWA, you may import a train schedule CSV. Train schedules are stored in a separate private SQLite database on your device. On Web/PWA and Android, you may export or restore that database as a user-controlled local backup file. The app does not upload those CSV files, schedules, or backups to the developer or a cloud service.</p><p>On the web, a service worker may cache app files so the app can open after a prior load. Your browser may remove cached files or stored packs under its storage rules. Android backup and device transfer are disabled for the app&#39;s private data.</p><h2 id="network-use" tabindex="-1">Network use <a class="header-anchor" href="#network-use" aria-label="Permalink to &quot;Network use&quot;">​</a></h2><p>Opening the Offline Data screen checks a public data-pack manifest for updates. A pack is downloaded only when you choose to install it. The app gets the manifest and pack files over HTTPS from publicly hosted sources, and verifies downloaded pack integrity before replacing an installed pack. MetroPocket does not send your route searches, selected stations, or TV channel lookups with those requests. Web hosting and data-file hosts may receive standard connection information, such as an IP address, under their own policies.</p><p>The web version also needs a connection for its initial load and for updates to the app shell. Previously cached content and installed data can then be used offline, subject to device and browser storage availability.</p><h2 id="permissions-and-sharing" tabindex="-1">Permissions and sharing <a class="header-anchor" href="#permissions-and-sharing" aria-label="Permalink to &quot;Permissions and sharing&quot;">​</a></h2><p>MetroPocket does not request GPS/location, contacts, camera, microphone, phone-state, notifications, or broad storage access for its current features. Android uses internet access for optional data updates. MetroPocket does not automatically share your route or channel activity with the developer or other users.</p><p>If you email support, the developer receives the information you choose to include. Your email provider and the recipient&#39;s email provider process that correspondence.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and deletion&quot;">​</a></h2><p>Installed packs, local preferences, and saved train schedules remain until you remove them, clear the app&#39;s storage, or uninstall the app. You can remove individual packs in <strong>Offline Data</strong> and delete all saved train schedules in <strong>Settings → Train Data</strong>. For all web data, clear MetroPocket&#39;s site data in your browser. For all Android data, clear MetroPocket&#39;s app storage in Android settings or uninstall it. Exported Train backup files remain where you chose to save them and must be deleted from that location separately. The developer has no account or cloud copy of your locally stored app data to delete. To request deletion of support correspondence, email the contact below.</p><h2 id="children-and-changes" tabindex="-1">Children and changes <a class="header-anchor" href="#children-and-changes" aria-label="Permalink to &quot;Children and changes&quot;">​</a></h2><p>MetroPocket is not designed to collect children&#39;s personal information through a developer-operated service. We may update this policy if the app or its data practices change; the dates above will be updated.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p><strong>Developer:</strong> Anand Raja<br><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></p>',20))])}const k=i(l,[["render",p]]);export{b as __pageData,k as default};
